// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint8 pick) public {
        vm.assume(pick < 2);
        Caller fresh = new Caller();
        Caller funded = new Caller();
        funded.go(c); // funded now holds 20 tokens
        Caller actor = pick == 0 ? fresh : funded;
        bool ok;
        try actor.go(c) { ok = true; } catch { ok = false; }
        assertTrue(
            pick == 1 || (ok && c.tokenBalance(address(actor)) == 20),
            "a valid Bank caller with zero balance must receive 20 tokens"
        );
    }
}

contract Caller is Bank {
    function go(ModifierEntrancy c) external {
        c.airDrop();
    }
}
